{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C30"],
      "claim": "Absolute oral bioavailability of morphine was 21.3% in a cancer patient, directly demonstrating that the N-methyl morphinan scaffold with a free phenol can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Morphine-d3 oral bioavailability was 37.2 ± 10.2% in opioid-dependent patients, supporting high oral F for a close isotopologue of the morphinan scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Codeine oral bioavailability is approximately 84% (range 74–94%), showing that related N-methyl morphinans can have high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Nalmefene absolute oral bioavailability is 40–50% in healthy subjects, supporting high oral F for morphinan opioids despite first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Naltrexone, a 6-keto morphinan with N-cyclopropylmethyl substitution, has ~5% oral bioavailability due to first-pass metabolism; this is the main low-F analogue, but its N-substituent and antagonist-specific metabolism limit transfer to hydromorphone.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Hydromorphone is a 6-keto N-methyl morphinan. The closest high-quality analogues (morphine, morphine-d3, codeine, nalmefene) consistently show oral F ≥20%, often 30–80%, despite first-pass metabolism. The low-F naltrexone records are less transferable because of the N-cyclopropylmethyl substitution and antagonist-specific metabolism. Physicochemical properties (low MW, moderate logD, low TPSA, rigid scaffold) support absorption. Therefore predict high (F ≥20%).",
  "evidence_gaps": [
    "No direct hydromorphone experimental record is present in the provided evidence; inference relies on morphinan analogues.",
    "One morphine record (C27) reports very low F (0.84%) and conflicts with multiple other morphine absolute bioavailability estimates; its methodology is unclear.",
    "Morphine-6-glucuronide poor oral bioavailability is not transferable because it is a highly polar glucuronide conjugate."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

